public class Main {
    public int maxSubArrayLenBruteForce(int[] nums, int k) {
        int n = nums.length;
        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            int runningSum = 0;
            for (int j = i; j < n; j++) {
