def max_subarray_len(nums, k):
    prefix_sum = 0
    first_seen = {0: -1}
    max_len = 0
    for j, num in enumerate(nums):
        prefix_sum += num
        if (prefix_sum - k) in first_seen:
            max_len = max(max_len, j - first_seen[prefix_sum - k])
        if prefix_sum not in first_seen:
            first_seen[prefix_sum] = j
    return max_len


if __name__ == "__main__":
    nums = [1, -1, 5, -2, 3]
    k = 3
    result = max_subarray_len(nums, k)
    print(result)

