public class Main {
    public int maxSubArrayLen(int[] nums, int k) {
        Map<Integer, Integer> firstSeen = new HashMap<>();
        firstSeen.put(0, -1);
        int prefixSum = 0;
        int maxLen = 0;
        for (int j = 0; j < nums.length; j++) {
            prefixSum += nums[j];
            if (firstSeen.containsKey(prefixSum - k)) {
                maxLen = Math.max(maxLen, j - firstSeen.get(prefixSum - k));
            }
            if (!firstSeen.containsKey(prefixSum)) {
                firstSeen.put(prefixSum, j);
            }
        }
        return maxLen;
    }

    public static void main(String[] args) {
        int[] nums = {1, -1, 5, -2, 3};
        int k = 3;
        Main solution = new Main();
        System.out.println(solution.maxSubArrayLen(nums, k));
