#include <bits/stdc++.h>
using namespace std;

int maxSubArrayLen(vector<int>& nums, int k) {
    unordered_map<int, int> firstSeen;
    firstSeen[0] = -1;
    int prefixSum = 0;
    int maxLen = 0;
    for (int j = 0; j < (int)nums.size(); j++) {
        prefixSum += nums[j];
        if (firstSeen.count(prefixSum - k)) {
            maxLen = max(maxLen, j - firstSeen[prefixSum - k]);
        }
        if (!firstSeen.count(prefixSum)) {
            firstSeen[prefixSum] = j;
        }
    }
    return maxLen;
}

int main() {
    vector<int> nums = {1, -1, 5, -2, 3};
    int k = 3;
    cout << maxSubArrayLen(nums, k) << endl;
    return 0;
}
